[CmdletBinding()] param([string]$FbeExe=(Join-Path $PSScriptRoot '..\..\out\Release\FBE.exe'),[int]$TimeoutSeconds=90)
$ErrorActionPreference='Stop';$dir=Join-Path ([IO.Path]::GetTempPath()) ('fbe-clipboard-fallback-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $dir|Out-Null
try{$f=Join-Path $dir 'f.fb2';$r=Join-Path $dir 'r.tsv';'<?xml version="1.0"?><FictionBook xmlns="http://www.gribuser.ru/xml/fictionbook/2.0"><description><title-info><genre>prose</genre><author><first-name>T</first-name><last-name>T</last-name></author><book-title>T</book-title><lang>en</lang></title-info><document-info><program-used>T</program-used><id>T</id><version>1</version></document-info></description><body><section><p>T</p></section></body></FictionBook>'|Set-Content $f -Encoding utf8;$a,$b,$c=$env:FBE_NEXT_TEST_MODE,$env:FBE_NEXT_TEST_SCENARIO,$env:FBE_NEXT_TRACE;$env:FBE_NEXT_TEST_MODE='1';$env:FBE_NEXT_TEST_SCENARIO='clipboard-fallback';$env:FBE_NEXT_TRACE='1';try{$p=Start-Process $FbeExe -ArgumentList @('-b',$r,$f) -PassThru;if(!$p.WaitForExit($TimeoutSeconds*1000)){Stop-Process $p -Force;throw 'timeout'}}finally{$env:FBE_NEXT_TEST_MODE,$env:FBE_NEXT_TEST_SCENARIO,$env:FBE_NEXT_TRACE=$a,$b,$c};$x=@{};Get-Content $r|%{$q=$_-split "`t",2;$x[$q[0]]=[int]$q[1]};if($p.ExitCode -ne 0 -or $x.clipboard_checks -ne 1 -or $x.bitmap_detected -ne 1){throw 'fallback failed'}}finally{Remove-Item $dir -Recurse -Force -ErrorAction SilentlyContinue}
